    "area": "Recursos Humanos",
    "title": "Recorrido de Aprendizaje en Métricas de Recursos Humanos",
    "rationale": "Este recorrido está diseñado para comprender, calcular e interpretar las principales métricas de gestión del capital humano, abarcando desde la eficiencia en la contratación hasta la retención, el desarrollo y la satisfacción del personal.",
    "modules": [
      {
        "position": 1,
        "metric": "Costo por Contratación",
        "reason": "Permite medir la eficiencia económica y la inversión total requerida para incorporar un nuevo colaborador al equipo."
      },
      {
        "position": 2,
        "metric": "Tasa de Rotación de Nuevos Contratados",
        "reason": "Evalúa el porcentaje de empleados que dejan la organización durante sus primeros meses, reflejando la efectividad del proceso de selección y onboarding."
      },
      {
        "position": 3,
        "metric": "Tasa de Promoción",
        "reason": "Mide los esfuerzos de desarrollo interno y movilidad de carrera dentro de la organización."
      },
      {
        "position": 4,
        "metric": "Tasa de Ausentismo",
        "reason": "Cuantifica las jornadas de trabajo perdidas por ausencias imprevistas o planificadas, ayudando a identificar áreas críticas de clima o gestión."
      },
      {
        "position": 5,
        "metric": "Ingreso por Empleado",
        "reason": "Conecta la gestión del talento y la productividad general de la fuerza laboral con los resultados financieros del negocio."
      }
    ],
    "sources": [
      {
        "source_id": "src_shrm_extensis",
