        "tier": 3,
        "authority_reason": "Publicación profesional especializada en recursos humanos que recopila definiciones y benchmarks de la industria respaldados por el estándar SHRM."
      },
      {
        "source_id": "src_firsthr",
        "url": "https://firsthr.app/blog/core-hr/hr-metrics",
        "title": "HR Metrics to Track: Complete List With Benchmarks",
        "tier": 3,
        "authority_reason": "Guía profesional de análisis de recursos humanos enfocada en métricas de efectividad de prácticas y salud de la fuerza laboral."
      },
      {
        "source_id": "src_peoplebox",
        "url": "https://www.peoplebox.ai/blog/hr-metrics",
        "title": "HR Metrics: The Complete Guide For 2026",
